nextflow_process {

    name "Test Process QUARTO_NOTEBOOK"
    script "../main.nf"
    process "QUARTO_NOTEBOOK"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "quarto"
    tag "quarto/notebook"

    test("test notebook - [qmd:r]") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'generic/notebooks/quarto/quarto_r.qmd', checkIfExists: true) // Notebook
                ]
                input[1] = [:] // Parameters
                input[2] = [] // Input files
                input[3] = [] // Extensions
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    process.out.artifacts,
                    process.out.params_yaml
                ).match() },
                { assert path(process.out.html[0][1]).readLines().any { it.contains('Hello World 1') } },
            )
        }

    }

    test("test notebook - [qmd:python]") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
