                ]
                input[1] = [input_filename: "hello.txt", n_iter: 12] // Parameters
                input[2] = file(params.modules_testdata_base_path + 'generic/txt/hello.txt', checkIfExists: true) // Input files
                input[3] = [] // Extensions
                """
            }
        }

        then {
            assertAll(
