        // Enable per-test parameters
        ext.args = { params.module_args ?: '' }

        // Pinned: `task.cpus` is embedded in `params.yml` and included in the
        // rendered output, so leaving it unset breaks snapshot reproducibility
        // across machines.
        cpus = 1

